from typing import Callable, Sequence

def divides_for_all_residues(modulus: int, poly: Callable[[int], int]) -> bool:
    """Finite check behind the ZMod reduction: modulus | poly(x) for every
    residue x = 0..modulus-1 certifies modulus | poly(n) for ALL integers n."""
    return all(poly(x) % modulus == 0 for x in range(modulus))

def main() -> None:
    cases = [
        (5, lambda n: n ** 5 - n, "5 | n^5 - n   (fermat_little_five)"),
        (7, lambda n: n ** 7 - n, "7 | n^7 - n   (fermat_little_seven)"),
        (6, lambda n: n ** 3 - n, "6 | n^3 - n   (cube_sub_self_six)"),
    ]
    for m, f, label in cases:
        ok = divides_for_all_residues(m, f)
        spot: Sequence[int] = range(-10, 11)
        spot_ok = all(f(n) % m == 0 for n in spot)
        print(f"{label}: finite check={ok}, spot-check={spot_ok}")

if __name__ == "__main__":
    main()

import cmath
from typing import List, Sequence

def absolute_row_sums(M: Sequence[Sequence[float]]) -> List[float]:
    return [sum(abs(e) for e in row) for row in M]

def weak_gershgorin_bound(M: Sequence[Sequence[float]]) -> float:
    """Certified bound B = max_i sum_j |M_ij|; every eigenvalue |lambda| <= B."""
    return max(absolute_row_sums(M))

def eigenvalues_2x2(M: Sequence[Sequence[float]]) -> List[complex]:
    (a, b), (c, d) = M[0], M[1]
    tr, det = a + d, a * d - b * c
    disc = cmath.sqrt(tr * tr - 4 * det)
    return [(tr + disc) / 2, (tr - disc) / 2]

def main() -> None:
    for M in [[[2.0,-1.0],[0.5,3.0]], [[5.0,-2.0],[-3.0,1.0]]]:
        B = weak_gershgorin_bound(M)
        mags = [abs(z) for z in eigenvalues_2x2(M)]
        print(f"M={M} B={B} |eig|={[round(m,4) for m in mags]} "
              f"certified={all(m <= B + 1e-9 for m in mags)}")

if __name__ == "__main__":
    main()

from typing import Sequence, Tuple

def scalar_foldr_min(c: float, terms: Sequence[float], init: float) -> bool:
    """Distributive scalar-fold lemma: c + min(a_i, init) == min(c + a_i, c + init)."""
    left = c + min(list(terms) + [init])
    right = min([c + a for a in terms] + [c + init])
    return abs(left - right) < 1e-12

def tropical_normal_form(terms: Sequence[float]) -> Tuple[float, ...]:
    """AC-normal form: value is independent of grouping/order of min."""
    return tuple(sorted(terms))

def main() -> None:
    print("scalar_foldr_min:", scalar_foldr_min(3.0, [7.0, 2.0, 5.0], 9.0))
    print("normal form:", tropical_normal_form([7, 2, 5, 9]))

if __name__ == "__main__":
    main()

